  "}",
  "",
  "// Client Component — runs in browser too",
  "'use client';",
  "function AddToCart({ productId }: { productId: string }) {",
  "  const [added, setAdded] = useState(false); // useState works here",
  "  return <button onClick={() => setAdded(true)}>{added ? '✓' : 'Add to Cart'}</button>;",
  "}",
  "```",
